algorithm OperationsMenu
    define option as integer;
    define a as integer;
    define b as integer;
    read option, a, b;
    switch option do
        1:
            write a + b;
        2:
            write a - b;
        3:
            write a * b;
        4:
            write a / b;
        otherwise:
            write -1;
    endSwitch
endAlgorithm
